const PERSONAL_NOTES_HEADING = "## Personal Notes";

/**
 * Frontmatter keys written by the default template. Used to recognise notes
 * that were generated by this plugin before the `## Personal Notes` section
 * existed (upstream 5.x and earlier).
 */
const GENERATED_FRONTMATTER =
	/^(?:readStatus|percentRead|dateLastRead|timeSpentReading):/m;

export interface MergeResult {
	content: string;
	/**
	 * True when the existing note looked like a hand-written note and its whole
	 * body was preserved under the Personal Notes section instead of being
	 * silently replaced by the regenerated note.
	 */
	preservedForeignContent: boolean;
}

function findTerminator(rest: string, managedHeadings: string[]): number {
	const lines = rest.split("\n");
	let offset = 0;

	for (const line of lines) {
		const trimmed = line.trimEnd();
		if (trimmed.startsWith("## ")) {
			if (
				managedHeadings.length === 0 ||
				managedHeadings.includes(trimmed)
			) {
				return offset;
			}
		}
		offset += line.length + 1;
	}

	return -1;
}

/**
 * Extracts the `## Personal Notes` section of an existing note.
 *
 * `managedHeadings` are the level-2 headings the template regenerates after
 * the section. Only those end the section, so a user can freely add their own
 * `## Sub-section` inside their personal notes without losing it. When no
 * managed heading is known (custom template), any level-2 heading ends the
 * section.
 */
export function extractPersonalNotes(
	existingContent: string,
	managedHeadings: string[] = [],
): string | null {
	const idx = existingContent.lastIndexOf(PERSONAL_NOTES_HEADING);
	if (idx === -1) {
		return null;
	}

	const start = idx + PERSONAL_NOTES_HEADING.length;
	const rest = existingContent.substring(start);
	const terminator = findTerminator(rest, managedHeadings);

	if (terminator === -1) {
		return existingContent.substring(idx).trimEnd();
	}

	return existingContent.substring(idx, start + terminator).trimEnd();
}

/** Level-2 headings rendered after the Personal Notes placeholder. */
export function managedHeadingsAfterPlaceholder(newContent: string): string[] {
	const idx = newContent.lastIndexOf(PERSONAL_NOTES_HEADING);
	if (idx === -1) {
		return [];
	}

	const headings: string[] = [];
	for (const line of newContent.substring(idx).split("\n")) {
		const trimmed = line.trimEnd();
		if (trimmed.startsWith("## ")) {
			headings.push(trimmed);
		}
	}

	return headings;
}

export function looksPluginGenerated(content: string): boolean {
	return (
		content.includes(PERSONAL_NOTES_HEADING) ||
		GENERATED_FRONTMATTER.test(content)
	);
}

function normalizeForComparison(content: string): string {
	return content
		.replace(/\r\n/g, "\n")
		.split("\n")
		.map((line) => line.trimEnd())
		.join("\n")
		.trim();
}

/**
 * True when writing `next` over `existing` would not change anything the user
 * can see. Used to skip writes on re-import: no vault event, no sync churn, no
 * git diff for books that did not change.
 */
export function isContentEquivalent(existing: string, next: string): boolean {
	return normalizeForComparison(existing) === normalizeForComparison(next);
}

export function mergeContent(
	newContent: string,
	personalNotes: string | null,
): string {
	const section = (personalNotes ?? PERSONAL_NOTES_HEADING).trimEnd();
	const before = (() => {
		const idx = newContent.lastIndexOf(PERSONAL_NOTES_HEADING);
		return idx === -1
			? newContent.trimEnd()
			: newContent.substring(0, idx).trimEnd();
	})();

	const placeholderIdx = newContent.lastIndexOf(PERSONAL_NOTES_HEADING);
	if (placeholderIdx === -1) {
		return `${before}\n\n${section}`;
	}

	const afterPlaceholder = placeholderIdx + PERSONAL_NOTES_HEADING.length;
	const rest = newContent.substring(afterPlaceholder);
	const nextHeadingMatch = rest.search(/^## /m);

	if (nextHeadingMatch === -1) {
		return `${before}\n\n${section}`;
	}

	const after = rest.substring(nextHeadingMatch).trimStart();

	return `${before}\n\n${section}\n\n${after}`;
}

/**
 * Merges freshly rendered content with what already exists on disk.
 *
 * - No existing note: the rendered note is used as-is.
 * - Existing note with a Personal Notes section: only that section is kept.
 * - Existing note that does not look plugin-generated: its whole body is kept
 *   under Personal Notes, so a first import can never destroy user content.
 */
export function mergeImport(
	newContent: string,
	existingContent: string | null,
): MergeResult {
	if (existingContent === null || existingContent.trim().length === 0) {
		return {
			content: mergeContent(newContent, null),
			preservedForeignContent: false,
		};
	}

	const headings = managedHeadingsAfterPlaceholder(newContent);
	const personalNotes = extractPersonalNotes(existingContent, headings);

	if (personalNotes !== null) {
		return {
			content: mergeContent(newContent, personalNotes),
			preservedForeignContent: false,
		};
	}

	if (!looksPluginGenerated(existingContent)) {
		return {
			content: mergeContent(
				newContent,
				`${PERSONAL_NOTES_HEADING}\n\n${existingContent.trim()}`,
			),
			preservedForeignContent: true,
		};
	}

	return {
		content: mergeContent(newContent, null),
		preservedForeignContent: false,
	};
}
